import signal
import sys
import time

from gpiozero import OutputDevice
from gpiozero.exc import GPIOZeroError, GPIODeviceError

PINS = [2, 3, 4]
INTERVAL = 60

_running = True


def _handle_signal(signum, frame):
    global _running
    _running = False


def main():
    global _running

    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    devices = []
    try:
        for pin in PINS:
            try:
                dev = OutputDevice(pin)
                devices.append(dev)
            except (GPIOZeroError, GPIODeviceError) as exc:
                print(f"Error: failed to initialize GPIO {pin}: {exc}", file=sys.stderr)
                return 1
            except Exception as exc:
                print(f"Error: unexpected failure on GPIO {pin}: {exc}", file=sys.stderr)
                return 1

        while _running:
            for dev in devices:
                try:
                    dev.on()
                    print(f"GPIO {dev.pin.number} set to HIGH")
                except (GPIOZeroError, GPIODeviceError) as exc:
                    print(f"Error: failed to set GPIO {dev.pin.number} HIGH: {exc}", file=sys.stderr)
                    return 1
                except Exception as exc:
                    print(f"Error: unexpected failure setting GPIO {dev.pin.number} HIGH: {exc}", file=sys.stderr)
                    return 1

            for _ in range(INTERVAL):
                if not _running:
                    break
                time.sleep(1)

        return 0

    finally:
        for dev in devices:
            try:
                dev.close()
            except Exception:
                pass


if __name__ == "__main__":
    sys.exit(main())

import time
import sys
import signal
import board
import busio
import adafruit_ads1x15.ads1115 as ADS
from adafruit_ads1x15.analog_in import AnalogIn

# Constants
ADC_ADDRESS = 0x48
ADC_CHANNEL = 0
SAMPLE_INTERVAL = 0.1
MAX_RETRIES = 3

# Global flag for graceful shutdown
_running = True


def _signal_handler(signum, frame):
    """Handle SIGINT/SIGTERM for clean shutdown."""
    global _running
    _running = False


def initialize_adc():
    """Initialize the I2C bus and ADS1115 ADC.

    Returns:
        AnalogIn: Configured ADC channel object.

    Raises:
        RuntimeError: If the I2C bus or ADC cannot be initialized.
    """
    try:
        i2c = busio.I2C(board.SCL, board.SDA)
    except Exception as e:
        raise RuntimeError(f"Failed to initialize I2C bus: {e}") from e

    try:
        ads = ADS.ADS1115(i2c, address=ADC_ADDRESS)
    except ValueError as e:
        raise RuntimeError(
            f"ADS1115 not found at address 0x{ADC_ADDRESS:02X}: {e}"
        ) from e
    except Exception as e:
        raise RuntimeError(f"Failed to initialize ADS1115: {e}") from e

    try:
        channel = AnalogIn(ads, ADC_CHANNEL)
    except Exception as e:
        raise RuntimeError(f"Failed to configure ADC channel {ADC_CHANNEL}: {e}") from e

    return channel


def read_adc_value(channel):
    """Read a raw ADC value from the specified channel.

    Args:
        channel: AnalogIn object.

    Returns:
        int: Raw ADC value (16-bit signed).

    Raises:
        RuntimeError: If the reading fails after multiple retries.
    """
    for attempt in range(1, MAX_RETRIES + 1):
        try:
            value = channel.value
            if value is None:
                raise RuntimeError("ADC returned None")
            return value
        except Exception as e:
            if attempt < MAX_RETRIES:
                time.sleep(0.01)
            else:
                raise RuntimeError(
                    f"Failed to read ADC value after {MAX_RETRIES} attempts: {e}"
                ) from e


def main():
    """Main function to read and print ADC values."""
    global _running

    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    adc_channel = None
    try:
        adc_channel = initialize_adc()
        print(f"ADC initialized successfully. Reading channel {ADC_CHANNEL}...")

        while _running:
            try:
                adc_value = read_adc_value(adc_channel)
                print(f"ADC Value: {adc_value}")
            except RuntimeError as e:
                print(f"Error reading ADC: {e}", file=sys.stderr)

            # Sleep in small increments to allow prompt signal handling
            slept = 0.0
            while _running and slept < SAMPLE_INTERVAL:
                time.sleep(0.01)
                slept += 0.01

    except RuntimeError as e:
        print(f"Initialization error: {e}", file=sys.stderr)
        sys.exit(1)
    except Exception as e:
        print(f"Unexpected error: {e}", file=sys.stderr)
        sys.exit(1)
    finally:
        if adc_channel is not None:
            try:
                adc_channel.deinit()
            except Exception:
                pass
        print("ADC reading stopped.")


if __name__ == "__main__":
    main()

import signal
import sys
import time

from gpiozero import PWMOutputDevice
from gpiozero.exc import GPIOZeroError

PINS = [1, 2, 3, 4]
FREQUENCY = 1000
DELAY = 0.1

_running = True


def _handle_signal(signum, frame):
    global _running
    _running = False


def read_sensor_data():
    """Simulate reading sensor data. Returns a dict of pin -> value (0-100)."""
    return {pin: (i + 1) * 10 for i, pin in enumerate(PINS)}


def validate_data(data):
    """Validate sensor data. Returns True if all values are in [0, 100]."""
    return all(0 <= v <= 100 for v in data.values())


def apply_pwm(devices, data):
    """Apply PWM duty cycles to the devices based on sensor data."""
    for pin, device in devices.items():
        device.value = data[pin] / 100.0
    print(f"PWM applied: {data}")


def main():
    global _running

    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    devices = {}
    try:
        for pin in PINS:
            try:
                devices[pin] = PWMOutputDevice(pin, frequency=FREQUENCY)
            except GPIOZeroError as exc:
                print(f"Failed to initialize PWM on GPIO {pin}: {exc}", file=sys.stderr)
                return 1

        while _running:
            try:
                data = read_sensor_data()
            except Exception as exc:
                print(f"Sensor read error: {exc}", file=sys.stderr)
                time.sleep(DELAY)
                continue

            if not validate_data(data):
                print("Invalid sensor data. Skipping.", file=sys.stderr)
                time.sleep(DELAY)
                continue

            apply_pwm(devices, data)
            time.sleep(DELAY)

    except Exception as exc:
        print(f"Unexpected error: {exc}", file=sys.stderr)
        return 1
    finally:
        for device in devices.values():
            try:
                device.close()
            except Exception:
                pass
        print("GPIO cleanup completed.")

    return 0


if __name__ == "__main__":
    sys.exit(main())

