import serial
import time
import signal
import sys

SERIAL_PORT = '/dev/serial0'
BAUD_RATE = 9600
TIMEOUT_S = 1.0
READ_INTERVAL_S = 1.0
MAX_READ_ATTEMPTS = 3

_running = True

def _handle_signal(signum, frame):
    global _running
    _running = False

def read_sensor_data(serial_connection):
    """Read one line from the serial port and return it, or None on error/timeout."""
    try:
        raw = serial_connection.readline()
        if not raw:
            return None
        return raw.decode('ascii', errors='replace').strip()
    except serial.SerialException as e:
        print(f"Serial read error: {e}", file=sys.stderr)
        return None

def main():
    global _running

    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    try:
        serial_connection = serial.Serial(
            port=SERIAL_PORT,
            baudrate=BAUD_RATE,
            timeout=TIMEOUT_S,
            write_timeout=TIMEOUT_S,
        )
    except serial.SerialException as e:
        print(f"Failed to open {SERIAL_PORT}: {e}", file=sys.stderr)
        sys.exit(1)

    try:
        while _running:
            for attempt in range(1, MAX_READ_ATTEMPTS + 1):
                if not _running:
                    break
                data = read_sensor_data(serial_connection)
                if data is not None:
                    print(f"Sensor Reading: {data}")
                    break
                if attempt < MAX_READ_ATTEMPTS:
                    time.sleep(0.1)
            if _running:
                time.sleep(READ_INTERVAL_S)
    finally:
        if serial_connection.is_open:
            serial_connection.close()
            print("Serial port closed.")

if __name__ == "__main__":
    main()

