import signal
import sys
import time

from gpiozero import OutputDevice
from gpiozero.exc import GPIOZeroError

PIN = 17
CYCLES = 5
DELAY_S = 2.0

_running = True


def _handle_signal(signum, frame):
    global _running
    _running = False


def main():
    global _running

    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    try:
        output = OutputDevice(PIN)
    except GPIOZeroError as exc:
        print(f"Failed to initialize GPIO {PIN}: {exc}", file=sys.stderr)
        sys.exit(1)

    try:
        for i in range(CYCLES):
            if not _running:
                break

            try:
                output.on()
                print(f"Cycle {i + 1}/{CYCLES}: GPIO {PIN} -> HIGH")
            except GPIOZeroError as exc:
                print(f"Error setting GPIO {PIN} HIGH: {exc}", file=sys.stderr)
                break

            time.sleep(DELAY_S)

            if not _running:
                break

            try:
                output.off()
                print(f"Cycle {i + 1}/{CYCLES}: GPIO {PIN} -> LOW")
            except GPIOZeroError as exc:
                print(f"Error setting GPIO {PIN} LOW: {exc}", file=sys.stderr)
                break

            time.sleep(DELAY_S)

        if _running:
            print("GPIO state sequence completed.")
        else:
            print("Interrupted by signal; exiting.")
    finally:
        try:
            output.close()
        except Exception:
            pass


if __name__ == "__main__":
    main()

import signal
import sys
import logging
from gpiozero import PWMOutputDevice

logging.basicConfig(level=logging.INFO, format="%(asctime)s [%(levelname)s] %(message)s")
log = logging.getLogger("pwm_output")

PINS = [9, 10, 11, 12, 13]

devices = []
running = True


def cleanup():
    global devices
    for dev in devices:
        try:
            dev.close()
        except Exception:
            pass
    devices.clear()


def handle_signal(signum, frame):
    global running
    log.info("Signal %s received – shutting down.", signum)
    running = False


def main():
    global devices

    signal.signal(signal.SIGINT, handle_signal)
    signal.signal(signal.SIGTERM, handle_signal)

    try:
        for pin in PINS:
            dev = PWMOutputDevice(pin, frequency=1000, initial_value=0.0)
            devices.append(dev)
            log.info("PWM output initialised on GPIO %d (1 kHz, 0%% duty).", pin)
    except Exception as exc:
        log.error("Failed to initialise PWM on GPIO %s: %s", PINS, exc)
        cleanup()
        sys.exit(1)

    try:
        while running:
            try:
                raw = input("Enter PWM duty cycle (0-100): ").strip()
            except EOFError:
                log.info("EOF received – exiting.")
                break

            if not raw:
                continue

            try:
                duty = float(raw)
            except ValueError:
                log.error("Invalid input: '%s' – must be a number.", raw)
                continue

            if not (0.0 <= duty <= 100.0):
                log.error("Duty cycle must be between 0 and 100 – got %.2f.", duty)
                continue

            for dev in devices:
                dev.value = duty / 100.0
            log.info("Duty cycle set to %.2f%%.", duty)
    finally:
        cleanup()


if __name__ == "__main__":
    main()

import serial
import time
import signal
import sys

SERIAL_PORT = '/dev/serial0'
BAUD_RATE = 9600
TIMEOUT_S = 1.0
READ_INTERVAL_S = 5.0
MAX_RETRIES = 3

running = True

def handle_signal(signum, frame):
    global running
    running = False

def open_serial_port():
    try:
        return serial.Serial(SERIAL_PORT, BAUD_RATE, timeout=TIMEOUT_S)
    except serial.SerialException as e:
        print(f"Error opening serial port {SERIAL_PORT}: {e}", file=sys.stderr)
        return None

def read_sensor_data(serial_connection):
    for attempt in range(1, MAX_RETRIES + 1):
        try:
            raw = serial_connection.readline()
            if not raw:
                print("Warning: no data received (timeout).", file=sys.stderr)
                return None
            line = raw.decode('ascii', errors='replace').strip()
            if not line:
                return None
            return line
        except serial.SerialException as e:
            print(f"Serial read error (attempt {attempt}/{MAX_RETRIES}): {e}", file=sys.stderr)
            if attempt < MAX_RETRIES:
                time.sleep(0.5)
    return None

def process_data(data):
    if not data:
        return
    try:
        value = float(data)
        print(f"Sensor Reading: {value}")
    except ValueError:
        print(f"Invalid data received: {data}", file=sys.stderr)

def main():
    signal.signal(signal.SIGINT, handle_signal)
    signal.signal(signal.SIGTERM, handle_signal)

    serial_connection = open_serial_port()
    if serial_connection is None:
        sys.exit(1)

    try:
        while running:
            sensor_data = read_sensor_data(serial_connection)
            process_data(sensor_data)
            if running:
                time.sleep(READ_INTERVAL_S)
    except Exception as e:
        print(f"Unexpected error: {e}", file=sys.stderr)
    finally:
        if serial_connection and serial_connection.is_open:
            serial_connection.close()
            print("Serial port closed.")

if __name__ == "__main__":
    main()

import signal
import sys
import time

from gpiozero import OutputDevice
from gpiozero.exc import GPIOZeroError

# BCM pin assignments
PIN_A = 20
PIN_B = 21

# Timing
LOOP_DELAY = 0.5  # seconds

# Global references for signal handler
_devices = []


def _cleanup(signum=None, frame=None):
    """Release GPIO resources and exit cleanly."""
    for dev in _devices:
        try:
            dev.close()
        except Exception:
            pass
    if signum is not None:
        sys.exit(0)


def read_sensor_data():
    """Simulate reading sensor data. Returns a tuple (a, b) or None on error."""
    try:
        # In a real application, this would read from a sensor.
        # For demonstration, we return a fixed value.
        return (1, 0)
    except Exception as exc:
        print(f"Sensor read error: {exc}", file=sys.stderr)
        return None


def validate_data(data):
    """Validate sensor data. Returns True if valid, False otherwise."""
    if data is None:
        return False
    a, b = data
    if not isinstance(a, int) or not isinstance(b, int):
        return False
    if not (0 <= a <= 1) or not (0 <= b <= 1):
        return False
    return True


def apply_output(pin_a, pin_b, data):
    """Apply sensor data to GPIO outputs. Returns True on success, False on error."""
    try:
        pin_a.value = data[0]
        pin_b.value = data[1]
        print(f"GPIO {PIN_A} set to {data[0]}, GPIO {PIN_B} set to {data[1]}")
        return True
    except GPIOZeroError as exc:
        print(f"GPIO output error: {exc}", file=sys.stderr)
        return False
    except Exception as exc:
        print(f"Unexpected error during output: {exc}", file=sys.stderr)
        return False


def main():
    global _devices

    # Register signal handlers for clean shutdown
    signal.signal(signal.SIGINT, _cleanup)
    signal.signal(signal.SIGTERM, _cleanup)

    try:
        # Initialize GPIO outputs
        pin_a = OutputDevice(PIN_A)
        pin_b = OutputDevice(PIN_B)
        _devices = [pin_a, pin_b]

        print("Starting sensor data acquisition and output control...")

        while True:
            data = read_sensor_data()
            if validate_data(data):
                apply_output(pin_a, pin_b, data)
            else:
                print("Invalid sensor data received. Skipping output update.", file=sys.stderr)
            time.sleep(LOOP_DELAY)

    except GPIOZeroError as exc:
        print(f"GPIO initialization error: {exc}", file=sys.stderr)
        _cleanup()
        sys.exit(1)
    except Exception as exc:
        print(f"Unexpected error: {exc}", file=sys.stderr)
        _cleanup()
        sys.exit(1)


if __name__ == "__main__":
    main()

import signal
import sys
import time

from smbus2 import SMBus

AMG8833_ADDR = 0x69
AMG8833_REG_TEMP = 0x80

running = True

def handle_sigint(signum, frame):
    global running
    running = False

def read_temp(bus):
    data = bus.read_i2c_block_data(AMG8833_ADDR, AMG8833_REG_TEMP, 128)
    temps = []
    for i in range(0, 128, 2):
        raw = (data[i] << 8) | data[i + 1]
        if raw & 0x8000:
            raw -= 1 << 16
        temps.append(raw * 0.25)
    return temps

def main():
    global running
    signal.signal(signal.SIGINT, handle_sigint)
    bus = None
    try:
        bus = SMBus(1)
        while running:
            try:
                temps = read_temp(bus)
                print(temps)
            except OSError as e:
                print(f"I2C read error: {e}", file=sys.stderr)
            time.sleep(0.1)
    except Exception as e:
        print(f"Fatal error: {e}", file=sys.stderr)
    finally:
        if bus is not None:
            bus.close()

if __name__ == "__main__":
    main()

