import signal
import sys
import time

from gpiozero import DistanceSensor
from gpiozero.exc import GPIOZeroError, BadPinFactory

TRIGGER_PIN = 17
ECHO_PIN = 22
TIMEOUT = 5.0
SAMPLE_INTERVAL = 50.0
NUM_SAMPLES = 5

_running = True


def _handle_signal(signum, frame):
    global _running
    _running = False


def main():
    global _running

    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    try:
        sensor = DistanceSensor(
            echo=ECHO_PIN,
            trigger=TRIGGER_PIN,
            max_distance=4.0,
            threshold_distance=0.02,
        )
    except BadPinFactory:
        print("Error: no GPIO pin factory available (not running on a Raspberry Pi?).", file=sys.stderr)
        sys.exit(1)
    except GPIOZeroError as exc:
        print(f"Error: failed to initialize HC-SR04: {exc}", file=sys.stderr)
        sys.exit(1)

    try:
        for i in range(NUM_SAMPLES):
            if not _running:
                break

            try:
                distance_m = sensor.distance
            except GPIOZeroError as exc:
                print(f"Warning: read failed on sample {i + 1}: {exc}", file=sys.stderr)
                distance_m = None

            if distance_m is not None:
