import time

from gpiozero import DistanceSensor
from gpiozero.exc import GPIOZeroError, BadPinFactory

TRIG_PIN = 2
ECHO_PIN = 17
ECHO_TIMEOUT = 0.05  # 50 ms timeout for echo pulse

_running = True


def _handle_signal(signum, frame):
    global _running
    _running = False


def main():
    global _running

    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    try:
        sensor = DistanceSensor(
            echo=ECHO_PIN,
            trigger=TRIG_PIN,
            max_distance=4.0,
            threshold_distance=0.02,
        )
    except BadPinFactory:
        print("Error: No GPIO pin factory available. Are you running on a Raspberry Pi?", file=sys.stderr)
        sys.exit(1)
