        print(f"Error: Failed to initialize HC-SR04: {exc}", file=sys.stderr)
        sys.exit(1)

    try:
        deadline = time.monotonic() + ECHO_TIMEOUT
        while _running and time.monotonic() < deadline:
            try:
                distance = sensor.distance
            except GPIOZeroError:
                distance = None

            if distance is not None:
                print(f"Distance: {distance:.3f} m")
                break
            time.sleep(0.01)

        if not _running:
            print("\nInterrupted by signal.")
        else:
            print("Error: No echo received within timeout.")
    finally:
        sensor.close()


