    for pin_num, pin in PINS.items():
        try:
            sensors[pin_num] = adafruit_dht.DHT22(pin, use_pulseio=False)
        except Exception as exc:
            print(f"Warning: could not initialize DHT22 on GPIO {pin_num}: {exc}", file=sys.stderr)
            sensors[pin_num] = None

    try:
        while running:
            for pin_num, sensor in sensors.items():
                if sensor is None:
                    print(f"GPIO {pin_num}: sensor unavailable")
                    continue
                try:
                    temperature = sensor.temperature
