import signal
import sys
import time

from gpiozero import PWMOutputDevice
from gpiozero.exc import GPIOZeroError

PINS = [4, 17, 22, 27]
INTERVAL = 1.0
MAX_RETRIES = 3
RETRY_DELAY = 0.1

_running = True


def _handle_signal(signum, frame):
    global _running
    _running = False


def read_sensor(device):
    """Read a single PWM value from the device.

    Returns the float duty cycle (0.0–1.0) or None on failure.
    """
    for attempt in range(1, MAX_RETRIES + 1):
        try:
            return float(device.value)
        except (GPIOZeroError, OSError) as exc:
            print(f"  [read attempt {attempt}/{MAX_RETRIES}] read failed: {exc}",
                  file=sys.stderr)
            if attempt < MAX_RETRIES:
                time.sleep(RETRY_DELAY)
    return None


def validate_reading(value):
    """Return True if the reading is within the valid PWM range."""
    return value is not None and 0.0 <= value <= 1.0


def main():
    global _running

    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    devices = []
    try:
        for pin in PINS:
            try:
                dev = PWMOutputDevice(pin)
                dev.value = 0.0
                devices.append(dev)
            except GPIOZeroError as exc:
                print(f"Failed to initialize PWM on GPIO {pin}: {exc}",
                      file=sys.stderr)
                return 1

        while _running:
            for dev in devices:
                if not _running:
                    break
                value = read_sensor(dev)
                if validate_reading(value):
                    print(f"GPIO {dev.pin.number}: {value:.4f}")
                else:
                    print(f"GPIO {dev.pin.number}: invalid reading ({value})",
                          file=sys.stderr)
            if _running:
                time.sleep(INTERVAL)

    except Exception as exc:
        print(f"Unexpected error: {exc}", file=sys.stderr)
        return 1
    finally:
        for dev in devices:
            try:
                dev.value = 0.0
                dev.close()
            except Exception:
                pass
        print("GPIO cleanup completed.")

    return 0


if __name__ == "__main__":
    sys.exit(main())

