MAX_RETRIES = 3

running = True

def signal_handler(signum, frame):
    global running
    running = False

def read_sensor_data(ser):
    """Read one line from the serial port and return it stripped, or None on error."""
    try:
        raw = ser.readline()
        if not raw:
            return None
        return raw.decode('ascii', errors='replace').strip()
    except serial.SerialException as e:
        print(f"Serial read error: {e}", file=sys.stderr)
        return None

def validate_data(data):
    """Return True if the data string is a valid reading (3-digit integer)."""
    if not data:
        return False
    try:
        value = int(data)
    except ValueError:
        return False
    return 0 <= value <= 100

def main():
    global running
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    try:
