import serial
import sys
import signal

SERIAL_PORT = '/dev/serial0'
BAUD_RATE = 9600
TIMEOUT_S = 2.0

running = True

def handle_signal(signum, frame):
    global running
    running = False

def read_sensor_data(ser):
    """Read one line from the serial port and return it stripped."""
    try:
        raw = ser.readline()
    except serial.SerialException as e:
        print(f"Serial read error: {e}", file=sys.stderr)
        return None
    if not raw:
        print("Warning: no data received (timeout).", file=sys.stderr)
        return None
    return raw.decode('ascii', errors='replace').strip()

def validate_data(data):
    """Reject data that is not a valid integer within the expected range."""
    if not data:
        return False
    try:
        value = int(data)
    except ValueError:
        print(f"Warning: non-integer data received: {data!r}", file=sys.stderr)
        return False
    if not (-100 <= value <= 100):
        print(f"Warning: value out of range: {value}", file=sys.stderr)
        return False
    return True

def main():
    global running
    signal.signal(signal.SIGINT, handle_signal)
    signal.signal(signal.SIGTERM, handle_signal)

    try:
        ser = serial.Serial(
            port=SERIAL_PORT,
            baudrate=BAUD_RATE,
            timeout=TIMEOUT_S,
        )
    except serial.SerialException as e:
        print(f"Error: cannot open {SERIAL_PORT}: {e}", file=sys.stderr)
        sys.exit(1)

    try:
        data = read_sensor_data(ser)
        if data is None:
            sys.exit(0)
        if not validate_data(data):
            sys.exit(0)
        print(f"Sensor Reading: {data}")
    finally:
        ser.close()

if __name__ == '__main__':
    main()

