import signal
import sys
import time

import board
import adafruit_dht

PINS = {
    4: board.D4,
    7: board.D7,
    11: board.D11,
    17: board.D17,
}

_running = True


def _handle_signal(signum, frame):
    global _running
    _running = False


def main():
    global _running

    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    sensors = {}
    for pin_num, pin in PINS.items():
        try:
            sensors[pin_num] = adafruit_dht.DHT22(pin, use_pulseio=False)
        except Exception as exc:
            print(f"Error: failed to initialize DHT22 on GPIO {pin_num}: {exc}", file=sys.stderr)
            for s in sensors.values():
                try:
                    s.exit()
                except Exception:
                    pass
            sys.exit(1)

    try:
        while _running:
            for pin_num, sensor in sensors.items():
                try:
                    temperature = sensor.temperature
                    humidity = sensor.humidity

                    if temperature is None or humidity is None:
                        print(f"GPIO {pin_num}: no data (sensor absent or not ready)")
                        continue

                    if not (-40 <= temperature <= 80) or not (0 <= humidity <= 100):
                        print(f"GPIO {pin_num}: out-of-range reading (T={temperature}, H={humidity})")
                        continue

                    print(f"GPIO {pin_num}: Temperature = {temperature:.1f} C, Humidity = {humidity:.1f} %")

                except RuntimeError as exc:
                    # DHT22 checksum / timing glitches are common; retry next cycle.
                    print(f"GPIO {pin_num}: read error: {exc}")
                except Exception as exc:
                    print(f"GPIO {pin_num}: unexpected error: {exc}", file=sys.stderr)

            if _running:
                time.sleep(5)
    finally:
        for sensor in sensors.values():
            try:
                sensor.exit()
            except Exception:
                pass
        print("Program terminated.")


if __name__ == "__main__":
    main()

