from gpiozero import OutputDevice
from gpiozero.exc import GPIOZeroError

PINS = [5, 6]
CYCLES = 10
DELAY = 0.5

_running = True


def _handle_signal(signum, frame):
    global _running
    _running = False


def main():
    global _running

    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    devices = []
    try:
        for pin in PINS:
            try:
                dev = OutputDevice(pin)
                devices.append(dev)
            except GPIOZeroError as exc:
                print(f"Failed to initialize GPIO {pin}: {exc}", file=sys.stderr)
                return 1

        for i in range(CYCLES):
            if not _running:
                break

            states = []
            for dev in devices:
                try:
                    dev.on()
                    states.append(True)
                except GPIOZeroError as exc:
                    print(f"Error setting GPIO {dev.pin} HIGH: {exc}", file=sys.stderr)
                    return 1

            print(f"Cycle {i + 1}/{CYCLES}: GPIO {PINS[0]}=HIGH, GPIO {PINS[1]}=HIGH")

            for dev in devices:
                try:
                    dev.off()
                    states.append(False)
                except GPIOZeroError as exc:
                    print(f"Error setting GPIO {dev.pin} LOW: {exc}", file=sys.stderr)
                    return 1

            print(f"Cycle {i + 1}/{CYCLES}: GPIO {PINS[0]}=LOW, GPIO {PINS[1]}=LOW")

            if i < CYCLES - 1 and _running:
                time.sleep(DELAY)

    finally:
        for dev in devices:
            try:
                dev.close()
            except Exception:
                pass

    return 0


