import time

from gpiozero import PWMOutputDevice
from gpiozero.exc import GPIOZeroError

PINS = [12, 13, 18, 19, 22, 23]
FREQ = 1000
DELAY = 2.0

_running = True


def _handle_signal(signum, frame):
    global _running
    _running = False


def _validate(value):
    if not isinstance(value, (int, float)):
        raise ValueError("Value must be numeric")
    if not -1.0 <= value <= 1.0:
        raise ValueError("Value must be between -1.0 and 1.0")
    return float(value)


def main():
    global _running

    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    devices = []
    try:
        for pin in PINS:
            try:
                dev = PWMOutputDevice(pin=pin, frequency=FREQ, initial_value=0.0)
                devices.append(dev)
            except GPIOZeroError as exc:
                print(f"Failed to initialize PWM on GPIO {pin}: {exc}", file=sys.stderr)
                return 1

        while _running:
            try:
                value = float(input("Enter PWM value (-1.0 to 1.0): "))
            except EOFError:
                print("\nEOF received, exiting.")
                break
            except ValueError as exc:
                print(f"Invalid input: {exc}", file=sys.stderr)
                continue

            try:
                value = _validate(value)
            except ValueError as exc:
                print(f"Validation error: {exc}", file=sys.stderr)
                continue

            for dev in devices:
                dev.value = value
            print(f"PWM set to {value:.3f}")

            time.sleep(DELAY)

    except GPIOZeroError as exc:
        print(f"GPIO error: {exc}", file=sys.stderr)
        return 1
    finally:
        for dev in devices:
            try:
                dev.close()
            except Exception:
                pass
        print("GPIO cleanup completed.")

    return 0


if __name__ == "__main__":
    sys.exit(main())

