import signal
import sys
import time

from smbus2 import SMBus, i2c_msg

INA219_ADDRESS = 0x40
REG_CONFIG = 0x00
REG_SHUNT_VOLTAGE = 0x01
REG_BUS_VOLTAGE = 0x02
REG_POWER = 0x03
REG_CURRENT = 0x04
REG_CALIBRATION = 0x05

CONFIG_RESET = 0x8000
CONFIG_BRNG_16V = 0x0200
CONFIG_PGA_4_096MV = 0x0000
CONFIG_MODE_SHUNT_AND_BUS = 0x0003
CONFIG_DEFAULT = (
    CONFIG_RESET
    | CONFIG_BRNG_16V
    | CONFIG_PGA_4_096MV
    | CONFIG_MODE_SHUNT_AND_BUS
)

CALIBRATION_VALUE = 0x00000000

_running = True


def _handle_signal(signum, frame):
    global _running
    _running = False


def _write_config(bus, config):
    bus.write_word_data(INA219_ADDRESS, REG_CONFIG, config)


def _read_word(bus, reg):
    return bus.read_word_data(INA219_ADDRESS, reg)


def _read_shunt_voltage(bus):
    raw = _read_word(bus, REG_SHUNT_VOLTAGE)
    if raw & 0x8000:
        raw -= 1 << 16
    return raw * 0.00001


def _read_bus_voltage(bus):
    raw = _read_word(bus, REG_BUS_VOLTAGE)
    if raw & 0x8000:
        raw -= 1 << 16
    return raw * 0.004


def _read_power(bus):
    raw = _read_word(bus, REG_POWER)
    if raw & 0x8000:
        raw -= 1 << 16
    return raw * 0.000002


def _read_current(bus):
    raw = _read_word(bus, REG_CURRENT)
    if raw & 0x8000:
        raw -= 1 << 16
    return raw * 0.00004


def main():
    global _running

    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    bus = None
    try:
        bus = SMBus(1)
    except OSError as exc:
        print(f"Error: cannot open I2C bus 1: {exc}", file=sys.stderr)
        sys.exit(1)

    try:
        try:
            _write_config(bus, CONFIG_DEFAULT)
        except OSError as exc:
            print(f"Error: INA219 not found at 0x{INA219_ADDRESS:02X}: {exc}", file=sys.stderr)
            sys.exit(1)

        _write_config(bus, CONFIG_DEFAULT)

        count = 0
        while _running and count < 60:
            try:
                shunt_v = _read_shunt_voltage(bus)
                bus_v = _read_bus_voltage(bus)
                power = _read_power(bus)
                current = _read_current(bus)

                print(
                    f"Shunt Voltage: {shunt_v:.6f} V | "
                    f"Bus Voltage: {bus_v:.3f} V | "
                    f"Power: {power:.3f} W | "
                    f"Current: {current:.3f} A"
                )
            except OSError as exc:
                print(f"Warning: read error: {exc}", file=sys.stderr)

            count += 1
            if _running and count < 60:
                time.sleep(1)

    finally:
        if bus is not None:
            try:
                bus.close()
            except OSError:
                pass


if __name__ == "__main__":
    main()

