import signal
import sys
import time

import adafruit_dht
import board

# --- Configuration -----------------------------------------------------------
DHT_PIN = board.D22          # BCM GPIO 22 (physical pin 15)
READ_INTERVAL_S = 3.0
MAX_RETRIES = 3
RETRY_DELAY_S = 0.5

# --- Globals for cleanup -----------------------------------------------------
_running = True
_sensor = None


def _handle_signal(signum, frame):
    """Graceful shutdown on SIGINT / SIGTERM."""
    global _running
    _running = False


def _init_sensor():
    """Initialize the DHT22 on GPIO 22; return the sensor object or None."""
    try:
        return adafruit_dht.DHT22(DHT_PIN, use_pulseio=False)
    except Exception as exc:
        print(f"[ERROR] Failed to initialize DHT22 on GPIO 22: {exc}", file=sys.stderr)
        return None


def _read_sensor(sensor):
    """
    Attempt to read temperature (°C) and humidity (%) from the DHT22.
    Returns (temperature, humidity) or (None, None) on failure.
    """
    for attempt in range(1, MAX_RETRIES + 1):
        try:
            temperature = sensor.temperature
            humidity = sensor.humidity
            if temperature is None or humidity is None:
                raise RuntimeError("Sensor returned None")
            return temperature, humidity
        except RuntimeError as exc:
            # DHT22 checksum / timing glitches are common; retry.
            print(f"[WARN] Read attempt {attempt}/{MAX_RETRIES} failed: {exc}",
                  file=sys.stderr)
        except Exception as exc:
            # Unexpected error (e.g. device disconnected) — log and stop.
            print(f"[ERROR] Unexpected sensor error: {exc}", file=sys.stderr)
            return None, None
        if attempt < MAX_RETRIES:
            time.sleep(RETRY_DELAY_S)
    return None, None


def _report(temperature, humidity):
    """Print the current reading to stdout."""
    if temperature is not None and humidity is not None:
        print(f"Temperature: {temperature:.1f} °C")
        print(f"Humidity: {humidity:.1f} %")
    else:
        print("[ERROR] Failed to retrieve valid data from DHT22.", file=sys.stderr)


def main():
    global _sensor

    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    _sensor = _init_sensor()
    if _sensor is None:
        sys.exit(1)

    try:
        for cycle in range(1, 3):
            if not _running:
                break
            temperature, humidity = _read_sensor(_sensor)
            _report(temperature, humidity)
            if cycle < 2 and _running:
                time.sleep(READ_INTERVAL_S)
    finally:
        if _sensor is not None:
            try:
                _sensor.exit()
            except Exception:
                pass
        print("Program finished.")


if __name__ == "__main__":
    main()

import signal
import sys
import time

from gpiozero import OutputDevice
from gpiozero.exc import GPIOZeroError, DeviceClosed

# Configuration
GPIO_PINS = [17, 18]
READ_INTERVAL_SECONDS = 5
VALID_STATES = {0, 1}

# Global flag for graceful shutdown
_running = True


def _handle_signal(signum, frame):
    """Signal handler for SIGINT / SIGTERM."""
    global _running
    _running = False


def read_sensor_data():
    """Simulate reading sensor data. Returns a random integer in [0, 1]."""
    return 1


def validate_sensor_data(data):
    """Validate that the sensor data is within the expected range."""
    return data in VALID_STATES


def apply_control_action(device, state):
    """Set the GPIO output device to the given state."""
    device.value = state
    print(f"GPIO {device.pin.number} set to {state}")


def main():
    """Main loop: read sensor, validate, apply control, repeat every 5 s."""
    global _running

    # Register signal handlers for graceful shutdown
    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    devices = []
    try:
        # Initialize GPIO outputs
        for pin in GPIO_PINS:
            try:
                dev = OutputDevice(pin)
                devices.append(dev)
                print(f"Initialized GPIO {pin} as output (initial state: {dev.value})")
            except GPIOZeroError as exc:
                print(f"Error: failed to initialize GPIO {pin}: {exc}", file=sys.stderr)
                sys.exit(1)

        while _running:
            try:
                sensor_data = read_sensor_data()
                if not validate_sensor_data(sensor_data):
                    print(
                        f"Warning: invalid sensor data received ({sensor_data}); "
                        f"skipping control action",
                        file=sys.stderr,
                    )
                else:
                    for dev in devices:
                        apply_control_action(dev, sensor_data)
            except DeviceClosed:
                print("Error: GPIO device was closed unexpectedly.", file=sys.stderr)
                sys.exit(1)
            except GPIOZeroError as exc:
                print(f"Error during GPIO operation: {exc}", file=sys.stderr)
                sys.exit(1)

            # Sleep in small increments so signals are caught promptly
            slept = 0.0
            while _running and slept < READ_INTERVAL_SECONDS:
                time.sleep(0.1)
                slept += 0.1

    finally:
        # Clean resource release on all exit paths
        for dev in devices:
            try:
                dev.close()
                print(f"GPIO {dev.pin.number} released.")
            except Exception as exc:
                print(f"Warning: error releasing GPIO {dev.pin.number}: {exc}", file=sys.stderr)
        print("Program terminated.")


if __name__ == "__main__":
    main()

