import signal
import sys
import time

from gpiozero import PWMOutputDevice
from gpiozero.exc import GPIOZeroError, DeviceClosed

PWM_PINS = (15, 18)
FREQUENCY_HZ = 1000
DUTY_CYCLE = 0.5
MAX_INIT_RETRIES = 3
INIT_RETRY_DELAY_S = 0.5

_running = True


def _handle_signal(signum, frame):
    global _running
    _running = False


def _init_pwm(pin, frequency, duty_cycle):
    for attempt in range(1, MAX_INIT_RETRIES + 1):
        try:
            return PWMOutputDevice(pin, frequency=frequency, initial_value=duty_cycle)
        except GPIOZeroError as exc:
            print(f"Warning: failed to initialize PWM on GPIO {pin} (attempt {attempt}/{MAX_INIT_RETRIES}): {exc}", file=sys.stderr)
            if attempt < MAX_INIT_RETRIES:
                time.sleep(INIT_RETRY_DELAY_S)
    return None


def main():
    global _running

    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    pwm_devices = []
    try:
        for pin in PWM_PINS:
            pwm = _init_pwm(pin, FREQUENCY_HZ, DUTY_CYCLE)
            if pwm is None:
                print(f"Error: failed to initialize PWM on GPIO {pin} after {MAX_INIT_RETRIES} attempts.", file=sys.stderr)
                return 1
            pwm_devices.append(pwm)
            print(f"PWM initialized on GPIO {pin} at {FREQUENCY_HZ} Hz, duty cycle {duty_cycle * 100:.1f}%")

        print("Press Ctrl+C to stop.")

        while _running:
            time.sleep(0.1)

    except Exception as exc:
        print(f"Unexpected error: {exc}", file=sys.stderr)
        return 1
    finally:
        for pwm in pwm_devices:
            try:
                pwm.close()
            except DeviceClosed:
                pass
            except Exception as exc:
                print(f"Warning: error closing PWM device: {exc}", file=sys.stderr)
        print("GPIO cleanup completed.")

    return 0


if __name__ == "__main__":
    sys.exit(main())

