                break

            time.sleep(0.1)

        if not _running:
            print("Interrupted before GPIO 24 could be set.")
            return

        if time.monotonic() >= deadline:
            print(f"Timeout: GPIO {OUTPUT_PIN} did not respond within {MAX_WAIT_S}s.", file=sys.stderr)
            return

    finally:
        if output is not None:
            try:
                output.close()
            except Exception:
                pass


