import signal
import sys
import time

from gpiozero import OutputDevice
from gpiozero.exc import GPIOZeroError, GPIODeviceError

PINS = [5, 6, 20, 21]
VALID_STATES = {'on', 'off', '1', '0'}

_running = True


def _handle_signal(signum, frame):
    global _running
    _running = False


def read_state(pin):
    """Read a single state from stdin, validating it against VALID_STATES."""
    try:
        raw = input(f'Enter state for GPIO {pin} (on/off/1/0): ').strip().lower()
    except EOFError:
        print(f'Error: no input provided for GPIO {pin}.', file=sys.stderr)
        return None
    if raw not in VALID_STATES:
        print(f'Error: invalid state "{raw}" for GPIO {pin}. '
              f'Expected one of {sorted(VALID_STATES)}.', file=sys.stderr)
        return None
    return raw


def apply_state(pin, state):
    """Drive the given gpiozero OutputDevice to the requested state."""
    try:
        if state in ('on', '1'):
            pin.on()
        else:
            pin.off()
        print(f'GPIO {pin.pin.number} set to {state}')
    except (GPIOZeroError, GPIODeviceError) as exc:
        print(f'Error: failed to set GPIO {pin.pin.number} to {state}: {exc}',
              file=sys.stderr)
        return False
    return True


def main():
    global _running

    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    devices = []
    try:
        for pin in PINS:
            try:
                dev = OutputDevice(pin)
                devices.append(dev)
            except (GPIOZeroError, GPIODeviceError) as exc:
                print(f'Error: failed to initialize GPIO {pin}: {exc}',
                      file=sys.stderr)
                return 1

        for dev in devices:
            if not _running:
                break
            state = read_state(dev.pin.number)
            if state is None:
                continue
            apply_state(dev, state)

        return 0

    except Exception as exc:
        print(f'Unexpected error: {exc}', file=sys.stderr)
        return 1
    finally:
        for dev in devices:
            try:
                dev.close()
            except Exception:
                pass


if __name__ == '__main__':
    sys.exit(main())

