import time
import signal
import sys

SERIAL_PORT = '/dev/serial0'
BAUD_RATE = 9600
TIMEOUT = 1.0
READ_INTERVAL = 0.1
MAX_READ_ATTEMPTS = 3

running = True

def signal_handler(signum, frame):
    global running
    running = False

def read_sensor_data(ser):
    for attempt in range(1, MAX_READ_ATTEMPTS + 1):
        try:
            raw = ser.readline()
            if not raw:
                print(f"Attempt {attempt}/{MAX_READ_ATTEMPTS}: No data received (timeout).")
                continue
            line = raw.decode('ascii', errors='replace').strip()
            if not line:
                print(f"Attempt {attempt}/{MAX_READ_ATTEMPTS}: Empty line received.")
                continue
            return line
        except serial.SerialException as e:
            print(f"Attempt {attempt}/{MAX_READ_ATTEMPTS}: Serial read error: {e}")
            continue
    return None

def process_data(data):
    try:
        value = float(data)
        print(f"Sensor Reading: {value}")
    except ValueError:
        print(f"Invalid data received: {data!r}")

def main():
    global running
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    try:
        ser = serial.Serial(SERIAL_PORT, BAUD_RATE, timeout=TIMEOUT)
    except serial.SerialException as e:
        print(f"Error opening serial port {SERIAL_PORT}: {e}")
        sys.exit(1)

    try:
        while running:
            data = read_sensor_data(ser)
            if data is not None:
                process_data(data)
            time.sleep(READ_INTERVAL)
    finally:
        if ser.is_open:
            ser.close()
            print("Serial port closed.")

if __name__ == "__main__":
    main()

