import time

from gpiozero import PWMOutputDevice
from gpiozero.exc import GPIOZeroError, GPIODeviceError

PWM_PIN = 17
PWM_FREQUENCY = 1000
VALID_RANGE = (0.0, 1.0)

_running = True


def _handle_signal(signum, frame):
    global _running
    _running = False


def apply_pwm(device, value):
    if not isinstance(value, (int, float)):
        raise ValueError(f"PWM value must be numeric, got {type(value).__name__}")
    if not VALID_RANGE[0] <= value <= VALID_RANGE[1]:
        raise ValueError(f"PWM value {value} out of range {VALID_RANGE}")
    device.value = float(value)
    print(f"PWM applied: {value}")


def main():
    global _running

    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    try:
        pwm = PWMOutputDevice(PWM_PIN, frequency=PWM_FREQUENCY)
    except (GPIOZeroError, GPIODeviceError) as exc:
        print(f"Error: failed to initialize PWM on GPIO {PWM_PIN}: {exc}", file=sys.stderr)
        sys.exit(1)
    except Exception as exc:
        print(f"Unexpected error initializing GPIO {PWM_PIN}: {exc}", file=sys.stderr)
        sys.exit(1)

    try:
        while _running:
            try:
                apply_pwm(pwm, 0.5)
            except ValueError as exc:
                print(f"Warning: {exc}", file=sys.stderr)
            except (GPIOZeroError, GPIODeviceError) as exc:
                print(f"Error: failed to apply PWM: {exc}", file=sys.stderr)
                break

            time.sleep(1)
    finally:
        try:
            pwm.value = 0
            pwm.close()
        except Exception:
            pass
        print("PWM stopped and GPIO released.")


