import signal
import sys
import time

from gpiozero import PWMOutputDevice
from gpiozero.exc import GPIOZeroError, GPIODeviceError

PWM_PIN = 14
SAMPLE_INTERVAL = 5.0
MAX_RETRIES = 3
RETRY_DELAY = 0.5

_running = True


def _handle_signal(signum, frame):
    global _running
    _running = False


def read_pwm_value(device):
    """Read a PWM value from the device, retrying on transient errors."""
    for attempt in range(1, MAX_RETRIES + 1):
        try:
            return device.value
        except (GPIOZeroError, GPIODeviceError) as exc:
            print(f"Warning: read attempt {attempt}/{MAX_RETRIES} failed: {exc}",
                  file=sys.stderr)
            if attempt < MAX_RETRIES:
                time.sleep(RETRY_DELAY)
    return None


def validate_pwm_value(value):
    """Reject values outside the expected range."""
    if value is None:
        return False
    if not isinstance(value, (int, float)):
        print(f"Error: PWM value is not numeric: {value!r}", file=sys.stderr)
        return False
    if not (-1.0 <= value <= 1.0):
        print(f"Error: PWM value {value} out of range [-1, 1]", file=sys.stderr)
        return False
    return True


def main():
    global _running

    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    try:
        device = PWMOutputDevice(PWM_PIN)
    except (GPIOZeroError, GPIODeviceError) as exc:
        print(f"Error: failed to initialize PWM on GPIO {PWM_PIN}: {exc}",
              file=sys.stderr)
        sys.exit(1)

    try:
        while _running:
            value = read_pwm_value(device)
            if value is not None and validate_pwm_value(value):
                print(f"PWM value: {value}")
            else:
                print("Warning: skipping invalid reading", file=sys.stderr)

            # Sleep in small increments so signals are caught promptly
            slept = 0.0
            while _running and slept < SAMPLE_INTERVAL:
                time.sleep(0.1)
                slept += 0.1
    finally:
        try:
            device.close()
        except Exception:
            pass
        print("GPIO cleanup done.")


if __name__ == "__main__":
    main()

