import signal
import sys
import time

from w1thermsensor import W1ThermSensor, SensorNotReadyError, NoSensorFoundError

# DS18B20 GPIO pins (BCM numbering)
SENSOR_PINS = [4, 17]
READ_INTERVAL = 5  # seconds

_running = True


def _handle_signal(signum, frame):
    """Signal handler for graceful shutdown."""
    global _running
    _running = False


def _read_temperature(sensor):
    """Read temperature from a DS18B20 sensor, returning None on failure."""
    try:
        return sensor.get_temperature()
    except SensorNotReadyError:
        print(f"Warning: sensor {sensor.id} not ready, retrying...")
        return None
    except Exception as exc:
        print(f"Warning: unexpected error reading sensor {sensor.id}: {exc}")
        return None


def main():
    global _running

    # Register signal handlers for clean exit
    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    sensors = []
    try:
        # Initialize all configured pins
        for pin in SENSOR_PINS:
            try:
                sensors.append(W1ThermSensor(pin=pin))
            except NoSensorFoundError:
                print(f"Warning: no DS18B20 found on GPIO {pin}")
            except Exception as exc:
                print(f"Warning: failed to initialize GPIO {pin}: {exc}")

        if not sensors:
            print("Error: no DS18B20 sensors found. Check wiring and pull-up resistors.")
            sys.exit(1)

        print(f"Monitoring {len(sensors)} DS18B20 sensor(s) on pins {SENSOR_PINS}...")

        while _running:
            for sensor in sensors:
                if not _running:
                    break

                temp = _read_temperature(sensor)
                if temp is not None:
                    print(f"Sensor {sensor.id}: {temp:.2f} °C")

            # Sleep in small increments so signals are caught promptly
            slept = 0
            while _running and slept < READ_INTERVAL:
                time.sleep(0.5)
                slept += 0.5

    except Exception as exc:
        print(f"Fatal error: {exc}")
        sys.exit(1)
    finally:
        # Release hardware resources on all exit paths
        for sensor in sensors:
            try:
                sensor.close()
            except Exception:
                pass
        print("Program terminated.")


if __name__ == "__main__":
    main()

