import signal
import sys
import time

from smbus2 import SMBus

PCA9685_ADDRESS = 0x40
PCA9685_MODE1 = 0x00
PCA9685_PRESCALE = 0xFE
PCA9685_LED0_ON_L = 0x06

running = True
bus = None


def signal_handler(signum, frame):
    global running
    running = False


def write_register(bus, reg, value):
    bus.write_byte_data(PCA9685_ADDRESS, reg, value)


def read_register(bus, reg):
    return bus.read_byte_data(PCA9685_ADDRESS, reg)


def set_pwm_freq(bus, freq_hz):
    prescale = int(round(25e6 / 4096.0 / freq_hz) - 1)
    if prescale < 3 or prescale > 255:
        raise ValueError(f"Prescale {prescale} out of valid range (3-255)")
    old_mode = read_register(bus, PCA9685_MODE1)
    new_mode = (old_mode & 0x7F) | 0x10
    write_register(bus, PCA9685_MODE1, new_mode)
    write_register(bus, PCA9685_PRESCALE, prescale)
    write_register(bus, PCA9685_MODE1, old_mode)
    time.sleep(0.005)
    write_register(bus, PCA9685_MODE1, old_mode | 0x80)


def read_channel(bus, channel):
    if not 0 <= channel <= 15:
        raise ValueError(f"Channel must be 0-15, got {channel}")
    base = PCA9685_LED0_ON_L + 4 * channel
    on_l = read_register(bus, base)
    on_h = read_register(bus, base + 1)
    off_l = read_register(bus, base + 2)
    off_h = read_register(bus, base + 3)
    return (on_l & 0x0FFF) | ((on_h & 0x0F) << 12), (off_l & 0x0FFF) | ((off_h & 0x0F) << 12)


def main():
    global bus
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)
    try:
        bus = SMBus(1)
    except Exception as e:
        print(f"Failed to open I2C bus 1: {e}", file=sys.stderr)
        sys.exit(1)
    try:
        set_pwm_freq(bus, 60)
        while running:
            try:
                on, off = read_channel(bus, 0)
                print(f"Channel 0: ON={on}, OFF={off}")
            except Exception as e:
                print(f"Error reading channel 0: {e}", file=sys.stderr)
            time.sleep(0.005)
    finally:
        if bus is not None:
            try:
                write_register(bus, PCA9685_MODE1, 0x00)
            except Exception:
                pass
            bus.close()


if __name__ == "__main__":
    main()

import signal
import sys
from gpiozero import OutputDevice
from gpiozero.exc import GPIOZeroError

# Configuration
OUTPUT_PIN = 17
VALID_STATES = {"on", "off", "1", "0"}

# Global handle so the signal handler can release it
_output = None


def cleanup(signum=None, frame=None):
    """Release GPIO resources on exit or signal."""
    global _output
    if _output is not None:
        try:
            _output.close()
        except Exception:
            pass
        _output = None
    if signum is not None:
        sys.exit(0)


def apply_state(state_str):
    """Apply a validated state to the GPIO output and report it."""
    global _output
    if state_str not in VALID_STATES:
        raise ValueError(f"Invalid state '{state_str}'. Must be one of {VALID_STATES}")

    try:
        _output = OutputDevice(OUTPUT_PIN)
    except GPIOZeroError as exc:
        raise RuntimeError(f"Failed to initialize GPIO {OUTPUT_PIN}: {exc}") from exc

    if state_str in ("on", "1"):
        _output.on()
    else:
        _output.off()

    print(f"GPIO {OUTPUT_PIN} set to {'ON' if state_str in ('on', '1') else 'OFF'}")


def main():
    """Entry point: parse args, apply state, and clean up."""
    signal.signal(signal.SIGINT, cleanup)
    signal.signal(signal.SIGTERM, cleanup)

    try:
        apply_state("on")
    except (ValueError, RuntimeError) as exc:
        print(f"Error: {exc}", file=sys.stderr)
        cleanup()
        sys.exit(1)


if __name__ == "__main__":
    main()

import signal
import sys
import time

from gpiozero import OutputDevice
from gpiozero.exc import GPIOZeroError

PINS = [5, 6, 17, 18, 22, 23, 24, 27]
TIMEOUT_S = 1.0

_running = True


def _handle_signal(signum, frame):
    global _running
    _running = False


def main():
    global _running
    _running = True

    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    devices = []
    try:
        for pin in PINS:
            try:
                dev = OutputDevice(pin)
                devices.append(dev)
            except GPIOZeroError as exc:
                print(f"Failed to initialise GPIO {pin}: {exc}", file=sys.stderr)
                return 1

        print("GPIO pins initialised successfully.")

        for dev in devices:
            try:
                dev.on()
                print(f"GPIO {dev.pin.number} set to HIGH")
            except GPIOZeroError as exc:
                print(f"Failed to set GPIO {dev.pin.number} HIGH: {exc}", file=sys.stderr)
                return 1

        deadline = time.monotonic() + TIMEOUT_S
        while _running and time.monotonic() < deadline:
            time.sleep(0.1)

        if not _running:
            print("\nInterrupted by signal; releasing GPIO.")
        else:
            print("Timeout reached; releasing GPIO.")

    except Exception as exc:
        print(f"Unexpected error: {exc}", file=sys.stderr)
        return 1
    finally:
        for dev in devices:
            try:
                dev.close()
            except Exception:
                pass

    return 0


