import signal
import sys
import time

from gpiozero import PWMOutputDevice
from gpiozero.exc import GPIOZeroError, DeviceClosed

PINS = [5, 6, 13, 17, 18, 22, 23, 24, 27]
FREQ_HZ = 1000
DELAY_S = 1.0
MAX_RETRIES = 3
RETRY_DELAY_S = 0.1

_running = True


def _handle_signal(signum, frame):
    global _running
    _running = False


def _validate(value):
    if not isinstance(value, (int, float)):
        raise ValueError("Value must be numeric")
    if not -1.0 <= value <= 1.0:
        raise ValueError("Value must be between -1.0 and 1.0")
    return float(value)


def main():
    global _running

    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    devices = []
    try:
        for pin in PINS:
            try:
                dev = PWMOutputDevice(pin, frequency=FREQ_HZ, initial_value=0.0)
                devices.append(dev)
            except GPIOZeroError as exc:
                print(f"Error: failed to initialize PWM on GPIO {pin}: {exc}", file=sys.stderr)
                return 1

        while _running:
            for dev in devices:
                if not _running:
                    break
                for attempt in range(1, MAX_RETRIES + 1):
                    try:
                        value = _validate(dev.value)
                        dev.value = value
                        print(f"GPIO {dev.pin.number}: value={value:.4f}")
                        break
                    except (DeviceClosed, GPIOZeroError) as exc:
                        print(f"Warning: read failed on GPIO {dev.pin.number} (attempt {attempt}/{MAX_RETRIES}): {exc}", file=sys.stderr)
                        if attempt < MAX_RETRIES:
                            time.sleep(RETRY_DELAY_S)
                        else:
                            print(f"Error: giving up on GPIO {dev.pin.number}", file=sys.stderr)
                    except ValueError as exc:
                        print(f"Error: invalid value on GPIO {dev.pin.number}: {exc}", file=sys.stderr)
                        break

            if _running:
                time.sleep(DELAY_S)

    except GPIOZeroError as exc:
        print(f"Error: GPIO initialization failed: {exc}", file=sys.stderr)
        return 1
    finally:
        for dev in devices:
            try:
                dev.close()
            except Exception:
                pass
        print("GPIO cleanup completed.")

    return 0


if __name__ == "__main__":
    sys.exit(main())

