import serial
import time
import signal
import sys

SERIAL_PORT = '/dev/serial0'
BAUD_RATE = 9600
TIMEOUT_S = 2.0
READ_INTERVAL_S = 2.0
NUM_READINGS = 3

_running = True

def _handle_signal(signum, frame):
    global _running
    _running = False

def read_sensor_data(serial_port, baud_rate, timeout, num_readings, interval):
    global _running
    _running = True
    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    try:
        ser = serial.Serial(serial_port, baud_rate, timeout=timeout)
    except serial.SerialException as e:
        print(f"Error opening serial port {serial_port}: {e}", file=sys.stderr)
        return 1

    try:
        readings_taken = 0
        while _running and readings_taken < num_readings:
            try:
                raw = ser.readline()
            except serial.SerialException as e:
                print(f"Error reading from serial port: {e}", file=sys.stderr)
                return 1

            if not raw:
                print("Warning: no data received (timeout).", file=sys.stderr)
            else:
                try:
                    line = raw.decode('ascii', errors='replace').strip()
                except Exception as e:
                    print(f"Error decoding data: {e}", file=sys.stderr)
                    line = None

                if line:
                    print(f"Sensor Reading: {line}")
                    readings_taken += 1

            if _running and readings_taken < num_readings:
                time.sleep(interval)

        if not _running:
            print("\nInterrupted by user.", file=sys.stderr)
            return 130

        print(f"Completed {readings_taken} reading(s).")
        return 0

    finally:
        try:
            ser.close()
        except Exception:
            pass

if __name__ == "__main__":
    sys.exit(read_sensor_data(SERIAL_PORT, BAUD_RATE, TIMEOUT_S, NUM_READINGS, READ_INTERVAL_S))

import signal
import sys
import time

from smbus2 import SMBus, i2c_msg

TSL2591_ADDR = 0x29
TSL2591_CMD_BIT = 0xA0
TSL2591_REG_ENABLE = 0x00
TSL2591_REG_CONTROL = 0x01
TSL2591_REG_CHAN0_LOW = 0x14
TSL2591_REG_CHAN1_LOW = 0x16
TSL2591_ENABLE_POWERON = 0x01
TSL2591_CONTROL_GAIN_1X = 0x00
TSL2591_CONTROL_INTEGRATIONTIME_100MS = 0x00

_running = True


def _handle_signal(signum, frame):
    global _running
    _running = False


def _write_reg(bus, reg, value):
    write_msg = i2c_msg.write(TSL2591_ADDR, [TSL2591_CMD_BIT | reg, value])
    bus.i2c_rdwr(write_msg)


def _read_reg(bus, reg):
    write_msg = i2c_msg.write(TSL2591_ADDR, [TSL2591_CMD_BIT | reg])
    read_msg = i2c_msg.read(TSL2591_ADDR, 1)
    bus.i2c_rdwr(write_msg, read_msg)
    return list(read_msg)[0]


def _read_channel(bus, reg_low):
    data = bus.read_i2c_block_data(TSL2591_ADDR, TSL2591_CMD_BIT | reg_low, 2)
    return (data[1] << 8) | data[0]


def _init_sensor(bus):
    _write_reg(bus, TSL2591_REG_ENABLE, TSL2591_ENABLE_POWERON)
    _write_reg(bus, TSL2591_REG_CONTROL, TSL2591_CONTROL_GAIN_1X | TSL2591_CONTROL_INTEGRATIONTIME_100MS)


def _read_lux(bus):
    ch0 = _read_channel(bus, TSL2591_REG_CHAN0_LOW)
    ch1 = _read_channel(bus, TSL2591_REG_CHAN1_LOW)
    if ch0 == 0 or ch1 == 0:
        return None
    ratio = ch1 / ch0
    if ratio <= 0.52:
        lux = 0.0315 * ch0 - 0.0593 * ch0 * (ratio ** 1.4)
    elif ratio <= 0.65:
        lux = 0.0229 * ch0 - 0.0291 * ch1
    elif ratio <= 0.80:
        lux = 0.0157 * ch0 - 0.0180 * ch1
    elif ratio <= 1.3:
        lux = 0.00338 * ch0 - 0.00260 * ch1
    else:
        lux = 0.0
    return max(0.0, lux)


def main():
    global _running
    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    try:
        bus = SMBus(1)
    except OSError as e:
        print(f"Error: cannot open I2C bus 1: {e}", file=sys.stderr)
        sys.exit(1)

    try:
        try:
            _init_sensor(bus)
        except OSError as e:
            print(f"Error: TSL2591 not found at address 0x{TSL2591_ADDR:02X}: {e}", file=sys.stderr)
            sys.exit(1)

        readings = 0
        while _running and readings < 3:
            try:
                lux = _read_lux(bus)
            except OSError as e:
                print(f"Warning: I2C read error: {e}", file=sys.stderr)
                time.sleep(10)
                continue

            if lux is None:
                print("Warning: invalid reading (channel zero)", file=sys.stderr)
            else:
                print(f"Lux: {lux:.2f}")
                readings += 1

            if _running and readings < 3:
                time.sleep(10)

    finally:
        bus.close()


if __name__ == "__main__":
    main()

