import time

from gpiozero import PWMOutputDevice
from gpiozero.exc import GPIOZeroError

PWM_PIN = 18
VALID_RANGE = (0.0, 1.0)
MAX_RETRIES = 3
RETRY_DELAY = 0.5

_running = True


def _handle_signal(signum, frame):
    global _running
    _running = False


def read_pwm_value():
    """Read a PWM value from stdin. Returns None on EOF or invalid input."""
    try:
        raw = input("Enter PWM value (0.0-1.0): ").strip()
    except EOFError:
        return None
    if not raw:
        return None
    try:
        value = float(raw)
    except ValueError:
        print("Invalid input: not a number.", file=sys.stderr)
        return None
    if not (VALID_RANGE[0] <= value <= VALID_RANGE[1]):
        print(f"Invalid input: value {value} out of range {VALID_RANGE}.", file=sys.stderr)
        return None
    return value


def apply_pwm(pin, value):
    """Apply a PWM value to the given gpiozero PWMOutputDevice.

    Returns True on success, False on failure after retries.
    """
    for attempt in range(1, MAX_RETRIES + 1):
        try:
            pin.value = value
            print(f"PWM value applied: {value}")
            return True
        except GPIOZeroError as exc:
            print(f"GPIO error on attempt {attempt}/{MAX_RETRIES}: {exc}", file=sys.stderr)
            if attempt < MAX_RETRIES:
                time.sleep(RETRY_DELAY)
    return False


def main():
    global _running

    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    try:
        pwm = PWMOutputDevice(PWM_PIN)
    except GPIOZeroError as exc:
        print(f"Failed to initialize PWM on GPIO {PWM_PIN}: {exc}", file=sys.stderr)
        sys.exit(1)

    try:
        value = read_pwm_value()
        if value is None:
            print("No valid input received; exiting.", file=sys.stderr)
            return

        if not apply_pwm(pwm, value):
            print("Failed to apply PWM after retries; exiting.", file=sys.stderr)
            return

    finally:
        try:
            pwm.close()
        except Exception:
            pass
        print("GPIO cleanup completed.")


if __name__ == "__main__":
    main()

import time
import signal
import sys
from picamera2 import Picamera2

running = True

def handle_signal(signum, frame):
    global running
    running = False

signal.signal(signal.SIGINT, handle_signal)
signal.signal(signal.SIGTERM, handle_signal)

cam = None
try:
    cam = Picamera2()
    cam.start()
    while running:
        try:
            cam.capture_file("image.jpg")
        except Exception as e:
            print(f"Capture error: {e}", file=sys.stderr)
        time.sleep(0.2)
except Exception as e:
    print(f"Initialization error: {e}", file=sys.stderr)
finally:
    if cam is not None:
        try:
            cam.stop()
        except Exception:
            pass
    print("Program finished.")

import signal
import sys
from gpiozero import OutputDevice
from gpiozero.exc import GPIOZeroError

# BCM pin assignments
PINS = [17, 18]

# Global device handle so the signal handler can release it
_devices = []


def _cleanup(signum=None, frame=None):
    """Release all GPIO resources and exit cleanly."""
    for dev in _devices:
        try:
            dev.close()
        except Exception:
            pass
    _devices.clear()
    if signum is not None:
        sys.exit(0)


def apply_state(pin, state):
    """Drive *pin* to *state* (True = HIGH, False = LOW).

    Returns True on success, False on failure.
    """
    try:
        dev = OutputDevice(pin)
        _devices.append(dev)
        dev.value = 1 if state else 0
        print(f"GPIO {pin} set to {'HIGH' if state else 'LOW'}")
        return True
    except GPIOZeroError as exc:
        print(f"Error: failed to initialize GPIO {pin}: {exc}", file=sys.stderr)
        return False
    except Exception as exc:
        print(f"Unexpected error on GPIO {pin}: {exc}", file=sys.stderr)
        return False


def main():
    # Register signal handlers for clean shutdown on SIGINT / SIGTERM
    signal.signal(signal.SIGINT, _cleanup)
    signal.signal(signal.SIGTERM, _cleanup)

    # Apply state to each pin; exit on first failure
    for pin in PINS:
        if not apply_state(pin, True):
            _cleanup()
            sys.exit(1)

    # Keep the process alive briefly so the user can observe the state
    try:
        signal.pause()
    except KeyboardInterrupt:
        _cleanup()


if __name__ == "__main__":
    main()
